class AreaCalculator {
    double area(Shape s) {
        if (s instanceof Circle) {
            Circle c = (Circle) s;
            return Math.PI * c.r * c.r;
        } else if (s instanceof Rect) {
            Rect r = (Rect) s;
            return r.w * r.h;
        }
        return 0;
    }
}

